"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { DeltaBadge } from "@/registry/dashboardcn/ui/delta-badge"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"

export interface StageBarsStage {
  name: string
  value: number
  /** Any CSS color. Defaults to chart-1 through chart-5 in order. */
  color?: string
  /** Small icon drawn at the left end of the bar. */
  icon?: React.ReactNode
}

export interface StageBarsRange {
  value: string
  label: string
  /** Top of the funnel first. */
  stages: StageBarsStage[]
  /** Change in the first stage vs the previous range, as a fraction. */
  delta?: number
}

export interface StageBarsCardProps
  extends Omit<React.ComponentProps<typeof Card>, "children"> {
  title: string
  /** Top of the funnel first. Ignored when `ranges` is set. */
  stages?: StageBarsStage[]
  /** Change in the first stage, as a fraction. Ignored when `ranges` is set. */
  delta?: number
  /** Context for the delta, e.g. "vs last week". */
  deltaLabel?: string
  invertDelta?: boolean
  /** Static text in the header, e.g. "Last 30 days". Replaced by the picker when `ranges` is set. */
  caption?: string
  /** Ranges for the header picker. Each carries its own stages. */
  ranges?: StageBarsRange[]
  range?: string
  defaultRange?: string
  onRangeChange?: (value: string) => void
  format?: NumberFormat
  currency?: string
  /** Any CSS color. Paints every bar in it, in place of the per-stage palette. */
  color?: string
  /** Show a tile with the name and value for each stage under the bars. */
  showTiles?: boolean
  /** Show the icons inside the bars. */
  showIcons?: boolean
}

const defaultColors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

/** The funnel as a list: a rounded bar per stage with its name, value, and share of the first stage. Hovering a stage swaps the headline. */
function StageBarsCard({
  title,
  stages: stagesProp = [],
  delta: deltaProp,
  deltaLabel,
  invertDelta,
  caption,
  ranges,
  range: rangeProp,
  defaultRange,
  onRangeChange,
  format = "number",
  currency,
  color,
  showTiles = true,
  showIcons = true,
  className,
  ...props
}: StageBarsCardProps) {
  const [rangeState, setRangeState] = React.useState(defaultRange ?? ranges?.[0]?.value)
  const range = rangeProp ?? rangeState
  const setRange = (value: string) => {
    setRangeState(value)
    onRangeChange?.(value)
  }
  const current = ranges?.find((option) => option.value === range) ?? ranges?.[0]
  const delta = current ? current.delta : deltaProp

  const first = (current?.stages ?? stagesProp)[0]
  const stages = (current?.stages ?? stagesProp).map((stage, index) => ({
    ...stage,
    share: first && first.value > 0 ? Math.min(1, Math.max(0, stage.value / first.value)) : 0,
    fill: stage.color ?? color ?? defaultColors[index % defaultColors.length],
    opacity: color && !stage.color ? 1 - index * (0.6 / Math.max(stagesProp.length - 1, 1)) : 1,
  }))

  const [active, setActive] = React.useState<number | null>(null)
  const hovered = active !== null ? stages[active] : undefined
  const headline = hovered ?? stages[0]
  const percent = (share: number) =>
    formatNumber(share, { format: "percent", maximumFractionDigits: 0 })

  return (
    <Card
      data-slot="stage-bars-card"
      className={cn("@container/card gap-4", className)}
      {...props}
    >
      <CardHeader>
        <CardDescription>{title}</CardDescription>
        <CardTitle className="text-3xl font-semibold tabular-nums tracking-tight">
          <MetricValue value={headline?.value ?? 0} format={format} currency={currency} />
        </CardTitle>
        <div className="flex h-5 items-center gap-1.5 text-sm">
          {hovered ? (
            <span className="text-muted-foreground truncate">
              {hovered.name}
              {hovered !== stages[0] ? (
                <>
                  {" · "}
                  <span className="text-foreground font-medium tabular-nums">
                    {percent(hovered.share)}
                  </span>{" "}
                  of {stages[0]?.name}
                </>
              ) : null}
            </span>
          ) : (
            <>
              {delta !== undefined ? (
                <DeltaBadge delta={delta} invert={invertDelta} variant="soft" />
              ) : null}
              {deltaLabel ? <span className="text-muted-foreground">{deltaLabel}</span> : null}
            </>
          )}
        </div>
        {ranges?.length ? (
          <CardAction>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm">
                  {current?.label}
                  <ChevronDown className="text-muted-foreground" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuRadioGroup value={range} onValueChange={setRange}>
                  {ranges.map((option) => (
                    <DropdownMenuRadioItem key={option.value} value={option.value}>
                      {option.label}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </CardAction>
        ) : caption ? (
          <CardAction>
            <span className="text-muted-foreground text-sm">{caption}</span>
          </CardAction>
        ) : null}
      </CardHeader>
      <CardContent className="flex flex-col gap-5">
        {/* Subgrid keeps the label column as wide as the longest name across every row. */}
        <div
          data-slot="stage-bars"
          role="list"
          className="grid grid-cols-[auto_minmax(0,1fr)_auto] gap-y-1"
          onMouseLeave={() => setActive(null)}
        >
          {stages.map((stage, index) => (
            <div
              key={stage.name}
              role="listitem"
              data-active={active === index || undefined}
              onMouseEnter={() => setActive(index)}
              className={cn(
                "col-span-3 grid grid-cols-subgrid items-center gap-x-3 rounded-md px-1 py-1 transition-opacity duration-200 -mx-1",
                active !== null && active !== index && "opacity-40"
              )}
            >
              <span className="text-muted-foreground truncate text-right text-sm">
                {stage.name}
              </span>
              <div className="bg-muted relative h-4 overflow-hidden rounded-full">
                <div
                  className="relative h-full rounded-full transition-[width] duration-500 ease-out"
                  style={{
                    width: `${Math.round(stage.share * 1000) / 10}%`,
                    minWidth: stage.icon && showIcons ? 16 : 4,
                    backgroundColor: stage.fill,
                    opacity: stage.opacity,
                  }}
                >
                  {stage.icon && showIcons ? (
                    <span className="text-background absolute inset-y-0 left-0 flex w-4 items-center justify-center [&>svg]:size-3">
                      {stage.icon}
                    </span>
                  ) : null}
                </div>
              </div>
              <span className="flex items-baseline justify-end gap-2 text-sm tabular-nums">
                <span className="font-medium">
                  {formatNumber(stage.value, { format, currency })}
                </span>
                <span className="text-muted-foreground w-9 text-right text-xs">
                  {percent(stage.share)}
                </span>
              </span>
            </div>
          ))}
        </div>
        {showTiles ? (
          <div className="grid grid-cols-2 gap-2 @xs/card:grid-cols-3">
            {stages.map((stage, index) => (
              <div
                key={stage.name}
                data-active={active === index || undefined}
                onMouseEnter={() => setActive(index)}
                onMouseLeave={() => setActive(null)}
                className={cn(
                  "flex min-w-0 flex-col gap-0.5 rounded-lg border px-2.5 py-2 transition-[opacity,border-color] duration-200",
                  active !== null && active !== index && "opacity-50",
                  active === index && "border-foreground/20"
                )}
              >
                <span className="text-muted-foreground flex items-center gap-1.5 text-xs">
                  <span
                    aria-hidden="true"
                    className="size-2 shrink-0 rounded-full"
                    style={{ backgroundColor: stage.fill, opacity: stage.opacity }}
                  />
                  <span className="truncate">{stage.name}</span>
                </span>
                <span className="truncate text-sm font-semibold tabular-nums">
                  {formatNumber(stage.value, { format, currency })}
                </span>
              </div>
            ))}
          </div>
        ) : null}
      </CardContent>
    </Card>
  )
}

export { StageBarsCard }

import * as React from "react"
import { Minus, TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatDelta } from "@/registry/dashboardcn/lib/format"

export type DeltaDirection = "up" | "down" | "flat"

export function getDeltaDirection(delta: number | undefined): DeltaDirection {
  if (delta === undefined || delta === 0 || !Number.isFinite(delta)) return "flat"
  return delta > 0 ? "up" : "down"
}

const directionIcon: Record<DeltaDirection, React.ElementType> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
}

export interface DeltaBadgeProps extends React.ComponentProps<"span"> {
  /** Fractional change, e.g. 0.124 for +12.4%. */
  delta: number
  /** Treat a decrease as good and an increase as bad (churn, latency, errors). */
  invert?: boolean
  variant?: "outline" | "soft" | "text"
  showIcon?: boolean
}

function DeltaBadge({
  delta,
  invert = false,
  variant = "outline",
  showIcon = true,
  className,
  children,
  ...props
}: DeltaBadgeProps) {
  const direction = getDeltaDirection(delta)
  const positive = direction === "flat" ? null : (direction === "up") !== invert
  const Icon = directionIcon[direction]

  return (
    <span
      data-slot="delta-badge"
      data-direction={direction}
      data-positive={positive}
      className={cn(
        "inline-flex items-center gap-1 text-xs font-medium tabular-nums",
        variant === "outline" && "rounded-md border px-1.5 py-0.5",
        variant === "soft" && "rounded-md px-1.5 py-0.5",
        variant === "soft" && positive === true && "bg-emerald-500/10",
        variant === "soft" && positive === false && "bg-red-500/10",
        variant === "soft" && positive === null && "bg-muted",
        positive === true && "text-emerald-600 dark:text-emerald-400",
        positive === false && "text-red-600 dark:text-red-400",
        positive === null && "text-muted-foreground",
        className
      )}
      {...props}
    >
      {showIcon ? <Icon className="size-3" aria-hidden="true" /> : null}
      {children ?? formatDelta(delta)}
    </span>
  )
}

export { DeltaBadge }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
